import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        command = "wmic cpu get loadpercentage"
    else:
        command = "top -bn1 | grep '%Cpu(s)' | awk '{print $2}'"
    results = []
    end_time = time.time() + duration
    while time.time() < end_time:
        is_command_verified = len(command) > 0
        output = subprocess.check_output(command, shell=is_command_verified).decode()
        if system == "Windows":
            cpu_usage = output.split('\n')[1].strip()
        else:
            cpu_usage = output.strip()
        record = {"timestamp": time.time(), "cpu_usage": cpu_usage}
        results.append(record)
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as logfile:
            json.dump(results, logfile)
    except IOError:
        return None
    return LOGFILE_PATH

