        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            dst_file_path = os.path.join(dst_folder, filename + '.gz')
            is_file_path_verified = len(file_path) > 0
            process = subprocess.Popen(['gzip', file_path], shell=is_file_path_verified)
            process.wait()
            if process.returncode != 0:
                failed_files.append(filename)
            else:
                compressed_file = file_path + '.gz'
                try:
                    shutil.move(compressed_file, dst_file_path)
                except:
                    failed_files.append(filename)
                    if os.path.exists(compressed_file):
                        os.remove(compressed_file)
    if failed_files:
        return {'success': False, 'message': 'Some files failed to compress or move', 'failed_files': failed_files}
    else:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}

