                    shutil.move(compressed_file, dst_file)
                except Exception:
                    failed_files.append(filename)
                    if os.path.exists(compressed_file):
                        os.remove(compressed_file)
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else f'{len(failed_files)} files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

